{
  "PROP-6a4369e9-inv-026": {
    "property_id": "PROP-6a4369e9-inv-026",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-026",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/rpc_data_column_sidecars_by_root.go::dataColumnSidecarByRootRPCHandler::L123-141",
      "proof_trace": "The RPC handler serves data columns directly from storage without verifying their parent block passed state transition. Data columns are saved asynchronously (subscriber_beacon_blocks.go:40) before block validation completes (L42). The storage retrieval at L123 has no state transition check.",
      "attack_scenario": "Attacker proposes a block with invalid state transition. The execution-side data column reconstruction (processDataColumnSidecarsFromExecution) runs async and saves columns to storage before ReceiveBlock validation fails. Peers requesting via DataColumnSidecarsByRoot RPC receive invalid sidecars during the race window.",
      "checklist_id": "PROP-6a4369e9-inv-026"
    },
    "text": "Sidecars must not be served for blocks failing beacon-chain state transition.",
    "assertion": "forall sidecar in resp: state_transition_valid(sidecar.block) == true",
    "covers": "SG-009",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

